LEVEL_ART = {"tutorial_notes": 1, "pr_fix_rerank": 2, "online_record": 3,
             "eval_report": 3, "design_doc": 4, "review_notes": 4,
             "team_spec": 5, "mentoring_log": 5}

def anchor_level(artifacts):
    return max((LEVEL_ART.get(a, 1) for a in artifacts), default=0)

def evidence_score(claim, arts, peer):
    return min(claim, anchor_level(arts), min(peer + 1, 5))

for claim, arts, peer in [(4, ["eval_report"], 1),
                          (3, ["tutorial_notes"], 3),
                          (2, ["online_record", "eval_report"], 2)]:
    eff = evidence_score(claim, arts, peer)
    print(f"claim={claim} eff={eff} {'降级' if eff < claim else '不降级'}")

KEYMAP = {"LangChain": ("工程", "模型"), "RAG": ("模型", "工程"),
          "评测集": ("工程", "产品"), "微调": ("模型", "工程"),
          "高并发": ("工程", "业务"), "A/B": ("产品", "工程"),
          "跨团队": ("业务", "产品"), "vLLM": ("模型", "工程")}

def jd_profile(jd_words):
    w = dict.fromkeys(["工程", "模型", "产品", "业务"], 0.0)
    for word, n in jd_words.items():
        if word not in KEYMAP:
            continue
        p, s = KEYMAP[word]
        w[p] += 1.0 * n
        w[s] += 0.5 * n
    tot = sum(w.values())
    return {k: v / tot for k, v in w.items()} if tot else w

def gaps(jd, mine, topn=2):
    return sorted(((d, jd[d] - mine[d]) for d in jd),
                  key=lambda x: x[1])[:topn]

jd = jd_profile({"RAG": 4, "LangChain": 3, "评测集": 2})
mine = {"工程": .45, "模型": .35, "产品": .10, "业务": .10}
print({k: round(v, 3) for k, v in jd.items()})
print("空JD:", jd_profile({}))
print("Top差距:", [(d, round(g, 3)) for d, g in gaps(jd, mine)])
